#!/usr/bin/env python3
"""Build EDTECH_SKILL_ALL_IN_ONE.md: SKILL.md + every reference + every template/script as code blocks,
for agents that accept only a single file. Run from the skill root:  python scripts/bundle_single_file.py"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
parts = [
    "<!-- AUTO-GENERATED by scripts/bundle_single_file.py — edit the source files, then rebuild. -->\n",
    "# Bangla EdTech Studio — ALL-IN-ONE\n",
    "> If you are an AI agent and cannot read the skill folder: everything is below. When you need a template "
    "or script, **write the code block to a file with the given filename** (e.g. `edtech.sty` next to your .tex) "
    "and compile with XeLaTeX. Image assets (logos) are not included — ask the user for their logo.\n",
    (ROOT / "SKILL.md").read_text(encoding="utf-8"),
]
for ref in sorted((ROOT / "references").glob("*.md")):
    parts.append(f"\n\n---\n\n<!-- file: references/{ref.name} -->\n" + ref.read_text(encoding="utf-8"))
LANG = {".sty": "latex", ".tex": "latex", ".py": "python", ".sh": "bash", ".json": "json"}
for sub, pats in (("templates", ["*.sty", "*.py"]), ("scripts", ["*.sh", "*.py"])):
    for pat in pats:
        for f in sorted((ROOT / sub).glob(pat)):
            if f.name == "bundle_single_file.py":
                continue
            parts.append(f"\n\n---\n\n### File: `{sub}/{f.name}`\n```{LANG.get(f.suffix, '')}\n"
                         + f.read_text(encoding="utf-8").rstrip() + "\n```\n")
out = ROOT / "EDTECH_SKILL_ALL_IN_ONE.md"
out.write_text("".join(parts), encoding="utf-8")
print(f"wrote {out} ({out.stat().st_size // 1024} KB)")
